/// One release whose vtable for an interface is not in the host's order.
pub struct SlotOrder {
    pub iface: &'static str,
    /// The release this order belongs to, as a `SpecId` discriminant.
    pub since: u8,
    /// For each position in that release's vtable, the slot in this host's table to put
    /// there. [`crate::hle::Hle::vtable_ordered`] writes these in order, so a guest that
    /// indexes by the release's own vtable calls the method it named.
    pub slots: &'static [u32],
}

/// Every interface whose published order differs from the host's. Built only where both
/// trees declare the interface *and* their slot names differ at the same index: a release
/// with fewer slots needs no map, because the host's first N are the same N.
pub const SLOT_ORDERS: &[SlotOrder] = &[SlotOrder {
    iface: "ICallHistory",
    since: 2,
    slots: &[0, 1, 2, 3, 4, 5, 7],
}];

/// The order for one interface at one release, if that release differs from the host.
pub fn slot_order(iface: &str, spec: SpecId) -> Option<&'static [u32]> {
    let since = spec as u8;
    SLOT_ORDERS
        .iter()
        .find(|o| o.since == since && o.iface == iface)
        .map(|o| o.slots)
}

/// The oldest release that declares an interface, if any record does.
pub fn iface_since(iface: &str) -> Option<SpecId> {
    IFACE_SINCE
        .binary_search_by(|(name, _)| (*name).cmp(iface))
        .ok()
        .map(|i| spec_of(IFACE_SINCE[i].1))
}

/// The oldest release that declares a class, if any record does.
pub fn clsid_since(clsid: u32) -> Option<SpecId> {
    CLSID_SINCE
        .binary_search_by(|(value, _)| (*value).cmp(&clsid))
        .ok()
        .map(|i| spec_of(CLSID_SINCE[i].1))
}

/// A discriminant back to the enum. Panics only on a value this table did not write.
fn spec_of(since: u8) -> SpecId {
    match since {
        SINCE_1_1 => SpecId::Classic1_1,
        SINCE_2_0 => SpecId::Classic2_0,
        SINCE_3_1 => SpecId::Classic3_1,
        SINCE_4_0 => SpecId::Classic4_0,
        SINCE_MP => SpecId::Mp7_12,
        other => panic!("no SpecId has discriminant {other}"),
    }
}
